#include <stdio.h>

#define MAXN 100005

int p[MAXN];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int k = 0;
    p[0] = 0;
    for (int i = 1; i <= n; i++) {
        int a;
        scanf("%d", &a);
        if (a == 1) {
            p[++k] = i;
        }
    }
    p[k + 1] = n + 1;

    long long total = 0;
    for (int i = 1; i <= k; i++) {
        long long left_choices = p[i] - p[i - 1];
        long long right_choices = p[i + 1] - p[i];
        total += left_choices * right_choices;
    }

    printf("%lld\n", total);

    return 0;
}
